// Quick bounding-box rejection
if (!P1.bb.intersects(P2.bb)) return false;

// Helper: orientation of triplet (p, q, r)
auto orient = [](const cg3::Point2d& p, const cg3::Point2d& q, const cg3::Point2d& r) -> int {
    double val = (q.y() - p.y()) * (r.x() - q.x()) - (q.x() - p.x()) * (r.y() - q.y());
    if (std::abs(val) < 1e-12) return 0;          // collinear
    return (val > 0) ? 1 : 2;                    // clock or counter-clock wise
};

// Helper: on-segment test (assumes collinearity)
auto onSegment = [](const cg3::Point2d& p, const cg3::Point2d& q, const cg3::Point2d& r) -> bool {
    return q.x() <= std::max(p.x(), r.x()) && q.x() >= std::min(p.x(), r.x()) &&
           q.y() <= std::max(p.y(), r.y()) && q.y() >= std::min(p.y(), r.y());
};

// Helper: segments (p1,q1) and (p2,q2) intersect?
auto segmentsIntersect = [&](const cg3::Point2d& p1, const cg3::Point2d& q1,
                             const cg3::Point2d& p2, const cg3::Point2d& q2) -> bool {
    int o1 = orient(p1, q1, p2);
    int o2 = orient(p1, q1, q2);
    int o3 = orient(p2, q2, p1);
    int o4 = orient(p2, q2, q1);

    if (o1 != o2 && o3 != o4) return true;

    if (o1 == 0 && onSegment(p1, p2, q1)) return true;
    if (o2 == 0 && onSegment(p1, q2, q1)) return true;
    if (o3 == 0 && onSegment(p2, p1, q2)) return true;
    if (o4 == 0 && onSegment(p2, q1, q2)) return true;

    return false;
};

// Check every edge pair
for (size_t i = 0; i < P1.size(); ++i) {
    const cg3::Point2d& a1 = P1[i];
    const cg3::Point2d& a2 = P1[(i + 1) % P1.size()];
    for (size_t j = 0; j < P2.size(); ++j) {
        const cg3::Point2d& b1 = P2[j];
        const cg3::Point2d& b2 = P2[(j + 1) % P2.size()];
        if (segmentsIntersect(a1, a2, b1, b2)) return true;
    }
}

// Point-in-polygon test for containment
auto pointInPolygon = [&](const cg3::Point2d& p, const cg3::Polygon2d& poly) -> bool {
    bool inside = false;
    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        const cg3::Point2d& vi = poly[i];
        const cg3::Point2d& vj = poly[j];
        if (((vi.y() > p.y()) != (vj.y() > p.y())) &&
            (p.x() < (vj.x() - vi.x()) * (p.y() - vi.y()) / (vj.y() - vi.y()) + vi.x()))
            inside = !inside;
    }
    return inside;
};

// Check if any vertex of P1 is inside P2 or vice-versa
for (const auto& v : P1.vectorPoints())
    if (pointInPolygon(v, P2)) return true;
for (const auto& v : P2.vectorPoints())
    if (pointInPolygon(v, P1)) return true;

return false;

